INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M32-CE002', 'HDSAT-RW-M32-CE002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'Language acquisition is the process by which humans acquire the capacity to perceive and comprehend language. In other words, it is how human beings gain the ability to be aware of language, to understand it, and to produce and use words and sentences to communicate. Language acquisition involves structures, rules, and representation. The capacity to successfully use language requires human beings to acquire a range of tools, including phonology, morphology, syntax, semantics, and an extensive vocabulary. Language can be vocalized as in speech, or manual as in sign. Human language capacity is represented in the brain. Even though human language capacity is finite, one can say and understand an effectively infinite number of sentences, which is based on a syntactic principle called recursion. Evidence suggests that every individual has three recursive mechanisms that allow sentences to go indeterminately. These three mechanisms are: relativization, complementation and coordination. There are two main guiding principles in first-language acquisition: speech perception always precedes speech production, and the gradually evolving system by which a child learns a language is built up one step at a time, beginning with the distinction between individual phonemes. For many years, linguists interested in child language acquisition have questioned how language is acquired. Lidz et al.', 'Which quotation from the text most directly supports the claim that recursion enables infinite sentences?', '[{"id": "A", "text": "There are two main guiding principles in first-language acquisition: speech perception always precedes speech production."}, {"id": "B", "text": "Language acquisition is the process by which humans acquire the capacity to perceive and comprehend language."}, {"id": "C", "text": "The capacity to successfully use language requires human beings to acquire a range of tools, including phonology, morphology, syntax, semantics, and an extensive vocabulary."}, {"id": "D", "text": "Even though human language capacity is finite, one can say and understand an effectively infinite number of sentences, which is based on a syntactic principle called recursion."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Language acquisition", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Language_acquisition', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M32-CE002', 'D', ARRAY['D']::TEXT[], 'The correct quotation links finite capacity and infinite sentences to recursion.', '{"B": "This sentence defines language acquisition.", "C": "This sentence lists the tools language users need.", "A": "This sentence states a developmental principle."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M32-CI003', 'HDSAT-RW-M32-CI003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Sign languages (also known as signed languages) are languages that use the visual-manual modality to convey meaning rather than spoken words. They are expressed through manual articulation in combination with non-manual markers, and are full-fledged natural languages with their own grammar and lexicon. Sign languages are not universal and are usually not mutually intelligible, although there are similarities among different sign languages. Wherever communities of deaf and hard of hearing people exist, sign languages have developed as a means of communication and form the core of local Deaf cultures. Although signing is used primarily by deaf and hard of hearing people, it is also used by hearing individuals, such as those with deaf family members including children of deaf adults (CODAs). Sign languages are distinct from body language, a type of nonverbal communication. Linguists also distinguish natural sign languages from other systems that are precursors to them or derived from them, such as constructed manual codes for spoken languages, home sign, baby sign language, and signs used with non-human primates. The number of sign languages worldwide is not precisely known. Each country generally has its own native sign language, and some have more than one. The 2021 edition of Ethnologue lists 150 sign languages, while the SIGN-HUB Atlas of Sign Language Structures lists over 200 and notes that there are more that have not yet been documented.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Sign languages are a form of body language."}, {"id": "B", "text": "Sign languages are universal and mutually intelligible."}, {"id": "C", "text": "Sign languages are full natural languages with their own grammar and lexicon, used mainly by deaf communities and varying around the world."}, {"id": "D", "text": "Sign languages lack grammar."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Sign language", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Sign_language', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M32-CI003', 'C', ARRAY['C']::TEXT[], 'The passage defines sign languages, describes their users and variation, and distinguishes them from related systems.', '{"B": "The text says they are not universal and usually not mutually intelligible.", "A": "The text says sign languages are distinct from body language.", "D": "The text says they are full-fledged natural languages with their own grammar."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M32-INF003', 'HDSAT-RW-M32-INF003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Sign languages (also known as signed languages) are languages that use the visual-manual modality to convey meaning rather than spoken words. They are expressed through manual articulation in combination with non-manual markers, and are full-fledged natural languages with their own grammar and lexicon. Sign languages are not universal and are usually not mutually intelligible, although there are similarities among different sign languages. Wherever communities of deaf and hard of hearing people exist, sign languages have developed as a means of communication and form the core of local Deaf cultures. Although signing is used primarily by deaf and hard of hearing people, it is also used by hearing individuals, such as those with deaf family members including children of deaf adults (CODAs). Sign languages are distinct from body language, a type of nonverbal communication. Linguists also distinguish natural sign languages from other systems that are precursors to them or derived from them, such as constructed manual codes for spoken languages, home sign, baby sign language, and signs used with non-human primates. The number of sign languages worldwide is not precisely known. Each country generally has its own native sign language, and some have more than one. The 2021 edition of Ethnologue lists 150 sign languages, while the SIGN-HUB Atlas of Sign Language Structures lists over 200 and notes that there are more that have not yet been documented.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M32-INF003', 'B', ARRAY['B']::TEXT[], 'Distinct, mutually unintelligible sign languages require learning the local one.', '{"D": "Lack of mutual intelligibility means a different sign language must be learned.", "A": "That contradicts the text''s statement.", "C": "The text says each country generally has its own native sign language."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M32-TS003', 'HDSAT-RW-M32-TS003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Sign languages (also known as signed languages) are languages that use the visual-manual modality to convey meaning rather than spoken words. They are expressed through manual articulation in combination with non-manual markers, and are full-fledged natural languages with their own grammar and lexicon. Sign languages are not universal and are usually not mutually intelligible, although there are similarities among different sign languages. Wherever communities of deaf and hard of hearing people exist, sign languages have developed as a means of communication and form the core of local Deaf cultures. Although signing is used primarily by deaf and hard of hearing people, it is also used by hearing individuals, such as those with deaf family members including children of deaf adults (CODAs). Sign languages are distinct from body language, a type of nonverbal communication. Linguists also distinguish natural sign languages from other systems that are precursors to them or derived from them, such as constructed manual codes for spoken languages, home sign, baby sign language, and signs used with non-human primates. The number of sign languages worldwide is not precisely known. Each country generally has its own native sign language, and some have more than one. The 2021 edition of Ethnologue lists 150 sign languages, while the SIGN-HUB Atlas of Sign Language Structures lists over 200 and notes that there are more that have not yet been documented.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It argues that sign languages should be standardized."}, {"id": "B", "text": "It defines sign languages, describes their users, distinguishes them from related systems, and notes how many exist."}, {"id": "C", "text": "It compares sign languages with written languages in a table."}, {"id": "D", "text": "It profiles a single Deaf community."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Sign language", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Sign_language', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
