INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M32-CE003', 'HDSAT-RW-M32-CE003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'Sign languages (also known as signed languages) are languages that use the visual-manual modality to convey meaning rather than spoken words. They are expressed through manual articulation in combination with non-manual markers, and are full-fledged natural languages with their own grammar and lexicon. Sign languages are not universal and are usually not mutually intelligible, although there are similarities among different sign languages. Wherever communities of deaf and hard of hearing people exist, sign languages have developed as a means of communication and form the core of local Deaf cultures. Although signing is used primarily by deaf and hard of hearing people, it is also used by hearing individuals, such as those with deaf family members including children of deaf adults (CODAs). Sign languages are distinct from body language, a type of nonverbal communication. Linguists also distinguish natural sign languages from other systems that are precursors to them or derived from them, such as constructed manual codes for spoken languages, home sign, baby sign language, and signs used with non-human primates. The number of sign languages worldwide is not precisely known. Each country generally has its own native sign language, and some have more than one. The 2021 edition of Ethnologue lists 150 sign languages, while the SIGN-HUB Atlas of Sign Language Structures lists over 200 and notes that there are more that have not yet been documented.', 'Which quotation from the text most directly supports the claim that sign languages are full languages?', '[{"id": "A", "text": "Sign languages are not universal and are usually not mutually intelligible."}, {"id": "B", "text": "Wherever communities of deaf and hard of hearing people exist, sign languages have developed as a means of communication."}, {"id": "C", "text": "They are expressed through manual articulation in combination with non-manual markers, and are full-fledged natural languages with their own grammar and lexicon."}, {"id": "D", "text": "Sign languages are languages that use the visual-manual modality to convey meaning rather than spoken words."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Sign language", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Sign_language', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M32-CE003', 'C', ARRAY['C']::TEXT[], 'The correct quotation calls them full-fledged natural languages with grammar and lexicon.', '{"D": "This sentence defines the modality.", "A": "This sentence describes variation.", "B": "This sentence describes their development in Deaf communities."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M32-CI004', 'HDSAT-RW-M32-CI004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Etymology ( ET-ih-MOL-ə-jee) is the study of the origin and evolution of words—including their constituent units of sound and meaning—across time. In the 21st century, as a subfield within linguistics, etymology has become an increasingly rigorous scientific field of study. It is most directly tied to historical linguistics, philology, and semiotics, and additionally draws upon comparative semantics, morphology, pragmatics, and phonetics in order to construct a comprehensive and chronological catalogue of all meanings that a word (and its related parts) has carried throughout its history. The origin of any particular word is also known as its etymology. For languages with a long written history, etymologists make use of texts, particularly texts about the language itself, to gather knowledge about how words were used during earlier periods, how they developed in meaning and form, or when and how they entered the language. Etymologists also apply the methods of comparative linguistics to reconstruct information about forms that are too old for any direct information to be available. By analyzing related languages with a technique known as the comparative method, linguists can make inferences about their shared parent language and its vocabulary. In this way, word roots in many European languages, for example, can be traced back to the origin of the Indo-European language family.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Etymology studies the origin and evolution of words, using historical texts and comparative linguistics to trace their development."}, {"id": "B", "text": "Etymology ignores the history of word meanings."}, {"id": "C", "text": "Etymology is limited to modern English."}, {"id": "D", "text": "Etymology studies the grammar of sentences."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Etymology", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Etymology', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
