INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M32-INF004', 'A', ARRAY['A']::TEXT[], 'Comparing related languages allows reconstruction of an unattested parent language.', '{"D": "The text says the comparative method lets linguists infer shared parent languages and vocabulary.", "B": "The text does not claim exact dating for every word.", "C": "The text says etymologists use texts for languages with long written histories."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
