INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M32-CE004', 'HDSAT-RW-M32-CE004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'Etymology ( ET-ih-MOL-ə-jee) is the study of the origin and evolution of words—including their constituent units of sound and meaning—across time. In the 21st century, as a subfield within linguistics, etymology has become an increasingly rigorous scientific field of study. It is most directly tied to historical linguistics, philology, and semiotics, and additionally draws upon comparative semantics, morphology, pragmatics, and phonetics in order to construct a comprehensive and chronological catalogue of all meanings that a word (and its related parts) has carried throughout its history. The origin of any particular word is also known as its etymology. For languages with a long written history, etymologists make use of texts, particularly texts about the language itself, to gather knowledge about how words were used during earlier periods, how they developed in meaning and form, or when and how they entered the language. Etymologists also apply the methods of comparative linguistics to reconstruct information about forms that are too old for any direct information to be available. By analyzing related languages with a technique known as the comparative method, linguists can make inferences about their shared parent language and its vocabulary. In this way, word roots in many European languages, for example, can be traced back to the origin of the Indo-European language family.', 'Which quotation from the text most directly supports the claim that etymology studies word origins?', '[{"id": "A", "text": "Etymologists also apply the methods of comparative linguistics to reconstruct information about forms that are too old for any direct information to be available."}, {"id": "B", "text": "Etymology is the study of the origin and evolution of words—including their constituent units of sound and meaning—across time."}, {"id": "C", "text": "In the 21st century, etymology has become an increasingly rigorous scientific field of study."}, {"id": "D", "text": "By analyzing related languages with a technique known as the comparative method, linguists can make inferences about their shared parent language."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Etymology", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Etymology', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M32-CE004', 'B', ARRAY['B']::TEXT[], 'The correct quotation defines etymology as the study of word origin and evolution.', '{"C": "This sentence describes the field''s development.", "A": "This sentence describes reconstruction methods.", "D": "This sentence describes the comparative method."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M32-CI005', 'HDSAT-RW-M32-CI005', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Phonetics is a branch of linguistics that mainly concerns the articulation, sound wave properties, and perception of speech sounds. The field of phonetics is traditionally divided into three sub-disciplines: articulatory phonetics, acoustic phonetics, and auditory phonetics. Linguists who specialize in studying these physical properties of vocalization are phoneticians. Traditionally, the minimal linguistic unit of phonetics is the phone, an individual speech sound. This differs from the minimal linguistic unit of phonology, the phoneme. Phonemes are abstract, language-specific categorizations of phones and are defined as the smallest units that affect meaning. The communicative modality of a language describes the method by which its production and perception occurs. Languages using oral-aural modalities such as English produce speech orally (using the mouth) and perceive speech aurally (using the ears). Languages using manual-visual modalities such as Australian Sign Language (Auslan) and American Sign Language (ASL) produce sign manually (using the hands) and perceive sign visually (using the eyes). ASL and some other sign languages have in addition a manual-manual dialect for use in tactile signing by deafblind speakers where signs are produced with the hands and perceived with the hands as well. Phonetics also addresses equivalent aspects of sign languages, and it includes the study of tactile signing.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Phonetics has no sub-disciplines."}, {"id": "B", "text": "Phonetics studies the articulation, acoustics, and perception of speech sounds, including equivalent aspects of sign languages."}, {"id": "C", "text": "Phonetics is limited to written language."}, {"id": "D", "text": "Phonetics studies the history of word meanings."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Phonetics", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Phonetics', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M32-CI005', 'B', ARRAY['B']::TEXT[], 'The passage defines phonetics, lists its branches, and distinguishes phones from phonemes.', '{"D": "The text names articulation, sound wave properties, and perception as its concerns.", "C": "The text says phonetics addresses equivalent aspects of sign languages.", "A": "The text divides the field into three sub-disciplines."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M32-INF005', 'HDSAT-RW-M32-INF005', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Hard', 'multiple_choice', 'Phonetics is a branch of linguistics that mainly concerns the articulation, sound wave properties, and perception of speech sounds. The field of phonetics is traditionally divided into three sub-disciplines: articulatory phonetics, acoustic phonetics, and auditory phonetics. Linguists who specialize in studying these physical properties of vocalization are phoneticians. Traditionally, the minimal linguistic unit of phonetics is the phone, an individual speech sound. This differs from the minimal linguistic unit of phonology, the phoneme. Phonemes are abstract, language-specific categorizations of phones and are defined as the smallest units that affect meaning. The communicative modality of a language describes the method by which its production and perception occurs. Languages using oral-aural modalities such as English produce speech orally (using the mouth) and perceive speech aurally (using the ears). Languages using manual-visual modalities such as Australian Sign Language (Auslan) and American Sign Language (ASL) produce sign manually (using the hands) and perceive sign visually (using the eyes). ASL and some other sign languages have in addition a manual-manual dialect for use in tactile signing by deafblind speakers where signs are produced with the hands and perceived with the hands as well. Phonetics also addresses equivalent aspects of sign languages, and it includes the study of tactile signing.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M32-INF005', 'C', ARRAY['C']::TEXT[], 'If categories are language-specific, one physical sound can be categorized differently across languages.', '{"A": "Language-specific categories mean each language classifies sounds its own way.", "B": "Phonemes concern sound categories, not meaning universally.", "D": "Phones are individual speech sounds that speakers produce."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M32-TS005', 'HDSAT-RW-M32-TS005', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Phonetics is a branch of linguistics that mainly concerns the articulation, sound wave properties, and perception of speech sounds. The field of phonetics is traditionally divided into three sub-disciplines: articulatory phonetics, acoustic phonetics, and auditory phonetics. Linguists who specialize in studying these physical properties of vocalization are phoneticians. Traditionally, the minimal linguistic unit of phonetics is the phone, an individual speech sound. This differs from the minimal linguistic unit of phonology, the phoneme. Phonemes are abstract, language-specific categorizations of phones and are defined as the smallest units that affect meaning. The communicative modality of a language describes the method by which its production and perception occurs. Languages using oral-aural modalities such as English produce speech orally (using the mouth) and perceive speech aurally (using the ears). Languages using manual-visual modalities such as Australian Sign Language (Auslan) and American Sign Language (ASL) produce sign manually (using the hands) and perceive sign visually (using the eyes). ASL and some other sign languages have in addition a manual-manual dialect for use in tactile signing by deafblind speakers where signs are produced with the hands and perceived with the hands as well. Phonetics also addresses equivalent aspects of sign languages, and it includes the study of tactile signing.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It argues that sign languages have no phonetics."}, {"id": "B", "text": "It compares English and French pronunciation in detail."}, {"id": "C", "text": "It defines phonetics, lists its three sub-disciplines, and distinguishes phones from phonemes."}, {"id": "D", "text": "It narrates a single experiment in speech perception."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Phonetics", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Phonetics', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
