INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M32-CE005', 'HDSAT-RW-M32-CE005', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'Phonetics is a branch of linguistics that mainly concerns the articulation, sound wave properties, and perception of speech sounds. The field of phonetics is traditionally divided into three sub-disciplines: articulatory phonetics, acoustic phonetics, and auditory phonetics. Linguists who specialize in studying these physical properties of vocalization are phoneticians. Traditionally, the minimal linguistic unit of phonetics is the phone, an individual speech sound. This differs from the minimal linguistic unit of phonology, the phoneme. Phonemes are abstract, language-specific categorizations of phones and are defined as the smallest units that affect meaning. The communicative modality of a language describes the method by which its production and perception occurs. Languages using oral-aural modalities such as English produce speech orally (using the mouth) and perceive speech aurally (using the ears). Languages using manual-visual modalities such as Australian Sign Language (Auslan) and American Sign Language (ASL) produce sign manually (using the hands) and perceive sign visually (using the eyes). ASL and some other sign languages have in addition a manual-manual dialect for use in tactile signing by deafblind speakers where signs are produced with the hands and perceived with the hands as well. Phonetics also addresses equivalent aspects of sign languages, and it includes the study of tactile signing.', 'Which quotation from the text most directly supports the claim that phonetics has three branches?', '[{"id": "A", "text": "Phonemes are abstract, language-specific categorizations of phones."}, {"id": "B", "text": "Traditionally, the minimal linguistic unit of phonetics is the phone, an individual speech sound."}, {"id": "C", "text": "The field of phonetics is traditionally divided into three sub-disciplines: articulatory phonetics, acoustic phonetics, and auditory phonetics."}, {"id": "D", "text": "Phonetics is a branch of linguistics that mainly concerns the articulation, sound wave properties, and perception of speech sounds."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Phonetics", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Phonetics', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M32-CE005', 'C', ARRAY['C']::TEXT[], 'The correct quotation names articulatory, acoustic, and auditory phonetics.', '{"D": "This sentence defines phonetics.", "B": "This sentence defines the phone.", "A": "This sentence defines the phoneme."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M32-CI006', 'HDSAT-RW-M32-CI006', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'In linguistics, grammar is the system of rules that governs how a natural language is structured and used, as evidenced by its speakers or writers. Grammar rules may concern the use of clauses, phrases, and words. The term may also refer to the study of such rules, a subject that includes phonology, morphology, and syntax, together with phonetics, semantics, and pragmatics. There are in effect two different ways to study grammar: traditional grammar and theoretical grammar. Fluency in a particular language variety involves a speaker internalizing these rules, many or most of which are acquired by observing other speakers, as opposed to intentional study or instruction. Much of this internalization occurs during early childhood; learning a language later in life usually involves more direct instruction. The term grammar can also describe the linguistic behaviour of groups of speakers and writers rather than individuals. Differences in scale can impact this definition: for example, English grammar could describe the rules followed by every one of the language''s speakers. At a smaller scale, it may refer to rules shared by smaller groups of speakers. A description, study, or analysis of such rules may also be known as a grammar, or as a grammar book. A reference work describing the grammar of a language is called a reference grammar or simply a grammar.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Grammar is learned only through formal instruction."}, {"id": "B", "text": "Grammar is the system of rules structuring a language, studied through traditional and theoretical approaches and largely acquired by exposure."}, {"id": "C", "text": "Grammar concerns only pronunciation."}, {"id": "D", "text": "Grammar is a set of rules that only written language follows."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Grammar", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Grammar', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M32-CI006', 'B', ARRAY['B']::TEXT[], 'The passage defines grammar, describes approaches to studying it, and explains how it is acquired.', '{"D": "The text says grammar governs how a natural language is structured and used.", "A": "The text says many rules are acquired by observing other speakers.", "C": "The text says much internalization occurs during early childhood."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M32-INF006', 'HDSAT-RW-M32-INF006', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'In linguistics, grammar is the system of rules that governs how a natural language is structured and used, as evidenced by its speakers or writers. Grammar rules may concern the use of clauses, phrases, and words. The term may also refer to the study of such rules, a subject that includes phonology, morphology, and syntax, together with phonetics, semantics, and pragmatics. There are in effect two different ways to study grammar: traditional grammar and theoretical grammar. Fluency in a particular language variety involves a speaker internalizing these rules, many or most of which are acquired by observing other speakers, as opposed to intentional study or instruction. Much of this internalization occurs during early childhood; learning a language later in life usually involves more direct instruction. The term grammar can also describe the linguistic behaviour of groups of speakers and writers rather than individuals. Differences in scale can impact this definition: for example, English grammar could describe the rules followed by every one of the language''s speakers. At a smaller scale, it may refer to rules shared by smaller groups of speakers. A description, study, or analysis of such rules may also be known as a grammar, or as a grammar book. A reference work describing the grammar of a language is called a reference grammar or simply a grammar.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M32-INF006', 'D', ARRAY['D']::TEXT[], 'Exposure to speakers, not formal instruction, drives much early grammar learning.', '{"A": "The text says many rules are acquired by observing other speakers.", "C": "The text contrasts observation with intentional study or instruction.", "B": "Textbooks are a form of instruction, which the text says is less central early on."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M32-TS006', 'HDSAT-RW-M32-TS006', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'In linguistics, grammar is the system of rules that governs how a natural language is structured and used, as evidenced by its speakers or writers. Grammar rules may concern the use of clauses, phrases, and words. The term may also refer to the study of such rules, a subject that includes phonology, morphology, and syntax, together with phonetics, semantics, and pragmatics. There are in effect two different ways to study grammar: traditional grammar and theoretical grammar. Fluency in a particular language variety involves a speaker internalizing these rules, many or most of which are acquired by observing other speakers, as opposed to intentional study or instruction. Much of this internalization occurs during early childhood; learning a language later in life usually involves more direct instruction. The term grammar can also describe the linguistic behaviour of groups of speakers and writers rather than individuals. Differences in scale can impact this definition: for example, English grammar could describe the rules followed by every one of the language''s speakers. At a smaller scale, it may refer to rules shared by smaller groups of speakers. A description, study, or analysis of such rules may also be known as a grammar, or as a grammar book. A reference work describing the grammar of a language is called a reference grammar or simply a grammar.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It argues that grammar should not be taught."}, {"id": "B", "text": "It lists every rule of English grammar."}, {"id": "C", "text": "It defines grammar, describes traditional and theoretical approaches, and explains how speakers acquire rules."}, {"id": "D", "text": "It profiles a single grammarian."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Grammar", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Grammar', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M32-TS006', 'C', ARRAY['C']::TEXT[], 'The passage moves from definition to approaches and acquisition.', '{"B": "No exhaustive rule list appears.", "D": "No grammarian is named.", "A": "The text says later learning usually involves more direct instruction."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M32-CE006', 'HDSAT-RW-M32-CE006', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'In linguistics, grammar is the system of rules that governs how a natural language is structured and used, as evidenced by its speakers or writers. Grammar rules may concern the use of clauses, phrases, and words. The term may also refer to the study of such rules, a subject that includes phonology, morphology, and syntax, together with phonetics, semantics, and pragmatics. There are in effect two different ways to study grammar: traditional grammar and theoretical grammar. Fluency in a particular language variety involves a speaker internalizing these rules, many or most of which are acquired by observing other speakers, as opposed to intentional study or instruction. Much of this internalization occurs during early childhood; learning a language later in life usually involves more direct instruction. The term grammar can also describe the linguistic behaviour of groups of speakers and writers rather than individuals. Differences in scale can impact this definition: for example, English grammar could describe the rules followed by every one of the language''s speakers. At a smaller scale, it may refer to rules shared by smaller groups of speakers. A description, study, or analysis of such rules may also be known as a grammar, or as a grammar book. A reference work describing the grammar of a language is called a reference grammar or simply a grammar.', 'Which quotation from the text most directly supports the claim that grammar is largely learned through exposure?', '[{"id": "A", "text": "The term grammar can also describe the linguistic behaviour of groups of speakers and writers rather than individuals."}, {"id": "B", "text": "There are in effect two different ways to study grammar: traditional grammar and theoretical grammar."}, {"id": "C", "text": "In linguistics, grammar is the system of rules that governs how a natural language is structured and used."}, {"id": "D", "text": "Fluency in a particular language variety involves a speaker internalizing these rules, many or most of which are acquired by observing other speakers, as opposed to intentional study or instruction."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Grammar", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Grammar', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M32-CE006', 'D', ARRAY['D']::TEXT[], 'The correct quotation says most rules are acquired by observing other speakers.', '{"C": "This sentence defines grammar.", "B": "This sentence names two approaches.", "A": "This sentence describes grammar at the group level."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M32-CI007', 'HDSAT-RW-M32-CI007', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Translation, in reference to language, is the communication of the meaning of a source-language text by means of an equivalent target-language text. The English language draws a terminological distinction (which does not exist in all languages) between translating written texts and interpreting oral or signed communications between languages. A translator always risks inadvertently introducing source-language words, grammar, or syntax into the target-language rendering. Such "spill-overs", however, have sometimes imported useful source-language calques and loanwords that have enriched target languages. Since the 1940s, efforts have been made, with varying degrees of success, to automate translation or to mechanically aid the human translator. More recently, the rise of the Internet has fostered a world-wide market for translation services and has facilitated "language localisation". == Etymology == The word for the concept of "translation", in English and some other European languages, stems from the Latin noun translatio, formed from the adverb trans, "across", and -latio, derived from latus, the past participle of the verb ferre, to "carry" or "bring". Thus, the Latin noun translatio and its cognate modern derivatives mean the "bringing across" (i.e., the transferring) of a text from one language to another.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Translation applies only to spoken language."}, {"id": "B", "text": "Translation is the study of ancient scripts."}, {"id": "C", "text": "Translation conveys meaning from a source language into a target language, risking spillovers but sometimes enriching the target language."}, {"id": "D", "text": "Translation never introduces source-language features."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Translation", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Translation', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M32-CI007', 'C', ARRAY['C']::TEXT[], 'The passage defines translation, describes its risks and benefits, and traces its history and etymology.', '{"B": "The text defines translation as communicating meaning through an equivalent target-language text.", "D": "The text says a translator always risks introducing source-language words, grammar, or syntax.", "A": "The text distinguishes translating written texts from interpreting oral or signed communication."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M32-INF007', 'HDSAT-RW-M32-INF007', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Translation, in reference to language, is the communication of the meaning of a source-language text by means of an equivalent target-language text. The English language draws a terminological distinction (which does not exist in all languages) between translating written texts and interpreting oral or signed communications between languages. A translator always risks inadvertently introducing source-language words, grammar, or syntax into the target-language rendering. Such "spill-overs", however, have sometimes imported useful source-language calques and loanwords that have enriched target languages. Since the 1940s, efforts have been made, with varying degrees of success, to automate translation or to mechanically aid the human translator. More recently, the rise of the Internet has fostered a world-wide market for translation services and has facilitated "language localisation". == Etymology == The word for the concept of "translation", in English and some other European languages, stems from the Latin noun translatio, formed from the adverb trans, "across", and -latio, derived from latus, the past participle of the verb ferre, to "carry" or "bring". Thus, the Latin noun translatio and its cognate modern derivatives mean the "bringing across" (i.e., the transferring) of a text from one language to another.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M32-INF007', 'A', ARRAY['A']::TEXT[], 'The passage states that borrowed forms from translation have enriched target languages.', '{"D": "The text says spillovers have enriched target languages.", "C": "The text describes enrichment, not damage.", "B": "The text says calques and loanwords have been imported."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M32-TS007', 'HDSAT-RW-M32-TS007', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Translation, in reference to language, is the communication of the meaning of a source-language text by means of an equivalent target-language text. The English language draws a terminological distinction (which does not exist in all languages) between translating written texts and interpreting oral or signed communications between languages. A translator always risks inadvertently introducing source-language words, grammar, or syntax into the target-language rendering. Such "spill-overs", however, have sometimes imported useful source-language calques and loanwords that have enriched target languages. Since the 1940s, efforts have been made, with varying degrees of success, to automate translation or to mechanically aid the human translator. More recently, the rise of the Internet has fostered a world-wide market for translation services and has facilitated "language localisation". == Etymology == The word for the concept of "translation", in English and some other European languages, stems from the Latin noun translatio, formed from the adverb trans, "across", and -latio, derived from latus, the past participle of the verb ferre, to "carry" or "bring". Thus, the Latin noun translatio and its cognate modern derivatives mean the "bringing across" (i.e., the transferring) of a text from one language to another.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It compares translation with editing."}, {"id": "B", "text": "It defines translation, explains its risks and benefits, describes automation efforts, and traces the word''s etymology."}, {"id": "C", "text": "It argues that machine translation is perfect."}, {"id": "D", "text": "It narrates a translator''s career."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Translation", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Translation', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M32-TS007', 'B', ARRAY['B']::TEXT[], 'The passage moves from definition to consequences, technology, and etymology.', '{"D": "No individual translator is profiled.", "A": "Editing is not discussed.", "C": "The text says automation efforts met with varying degrees of success."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M32-CE007', 'HDSAT-RW-M32-CE007', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'Translation, in reference to language, is the communication of the meaning of a source-language text by means of an equivalent target-language text. The English language draws a terminological distinction (which does not exist in all languages) between translating written texts and interpreting oral or signed communications between languages. A translator always risks inadvertently introducing source-language words, grammar, or syntax into the target-language rendering. Such "spill-overs", however, have sometimes imported useful source-language calques and loanwords that have enriched target languages. Since the 1940s, efforts have been made, with varying degrees of success, to automate translation or to mechanically aid the human translator. More recently, the rise of the Internet has fostered a world-wide market for translation services and has facilitated "language localisation". == Etymology == The word for the concept of "translation", in English and some other European languages, stems from the Latin noun translatio, formed from the adverb trans, "across", and -latio, derived from latus, the past participle of the verb ferre, to "carry" or "bring". Thus, the Latin noun translatio and its cognate modern derivatives mean the "bringing across" (i.e., the transferring) of a text from one language to another.', 'Which quotation from the text most directly supports the claim that translation can carry source-language features into the target?', '[{"id": "A", "text": "Translation is the communication of the meaning of a source-language text by means of an equivalent target-language text."}, {"id": "B", "text": "The word for the concept of translation stems from the Latin noun translatio."}, {"id": "C", "text": "A translator always risks inadvertently introducing source-language words, grammar, or syntax into the target-language rendering."}, {"id": "D", "text": "Since the 1940s, efforts have been made to automate translation or to mechanically aid the human translator."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Translation", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Translation', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M32-CE007', 'C', ARRAY['C']::TEXT[], 'The correct quotation names words, grammar, and syntax as possible spillovers.', '{"A": "This sentence defines translation.", "D": "This sentence describes automation efforts.", "B": "This sentence traces the word''s origin."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M32-CI008', 'HDSAT-RW-M32-CI008', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'A writing system is any conventional system for representing a particular language using a set of symbols (called a script), as well as the rules those symbols encode. The earliest of conventional writing systems appeared during the late 4th millennium BC. Throughout history, each independently invented writing system gradually emerged from a system of proto-writing, where a small number of ideographs were used in a manner incapable of fully encoding language, and thus lacking the ability to express a broad range of ideas. Writing systems are generally classified according to how their symbols, called graphemes, relate to units of language. Phonetic writing systems – which include alphabets and syllabaries – use graphemes that correspond to sounds in the corresponding spoken language. Alphabets use graphemes called letters that generally correspond to spoken phonemes. They are typically divided into three sub-types: Pure alphabets use letters to represent both consonant and vowel sounds, abjads generally only use letters representing consonant sounds, and abugidas use letters representing consonant–vowel pairs. Syllabaries use graphemes called syllabograms that represent entire syllables or moras. By contrast, logographic (or morphographic) writing systems use graphemes that represent the units of meaning in a language, such as its words or morphemes.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Writing systems represent language without any conventional symbols."}, {"id": "B", "text": "Writing systems first appeared in the 19th century."}, {"id": "C", "text": "Writing systems use conventional symbols to represent language and are classified by how graphemes relate to sounds or meaning."}, {"id": "D", "text": "All writing systems use alphabets."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Writing system", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Writing_system', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M32-CI008', 'C', ARRAY['C']::TEXT[], 'The passage defines writing systems, traces their origins, and explains their classification.', '{"A": "The text defines a writing system as conventional symbols and rules.", "D": "The text describes alphabets, syllabaries, and logographic systems.", "B": "The text says the earliest appeared during the late 4th millennium BC."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M32-INF008', 'HDSAT-RW-M32-INF008', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'A writing system is any conventional system for representing a particular language using a set of symbols (called a script), as well as the rules those symbols encode. The earliest of conventional writing systems appeared during the late 4th millennium BC. Throughout history, each independently invented writing system gradually emerged from a system of proto-writing, where a small number of ideographs were used in a manner incapable of fully encoding language, and thus lacking the ability to express a broad range of ideas. Writing systems are generally classified according to how their symbols, called graphemes, relate to units of language. Phonetic writing systems – which include alphabets and syllabaries – use graphemes that correspond to sounds in the corresponding spoken language. Alphabets use graphemes called letters that generally correspond to spoken phonemes. They are typically divided into three sub-types: Pure alphabets use letters to represent both consonant and vowel sounds, abjads generally only use letters representing consonant sounds, and abugidas use letters representing consonant–vowel pairs. Syllabaries use graphemes called syllabograms that represent entire syllables or moras. By contrast, logographic (or morphographic) writing systems use graphemes that represent the units of meaning in a language, such as its words or morphemes.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M32-INF008', 'A', ARRAY['A']::TEXT[], 'Limited encoding means limited expressive range, as the passage states.', '{"B": "The text says proto-writing was incapable of fully encoding language and thus lacked the ability to express a broad range of ideas.", "C": "Proto-writing used a small number of ideographs, not sound symbols.", "D": "The text describes it as a precursor, not a literary medium."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M32-TS008', 'HDSAT-RW-M32-TS008', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'A writing system is any conventional system for representing a particular language using a set of symbols (called a script), as well as the rules those symbols encode. The earliest of conventional writing systems appeared during the late 4th millennium BC. Throughout history, each independently invented writing system gradually emerged from a system of proto-writing, where a small number of ideographs were used in a manner incapable of fully encoding language, and thus lacking the ability to express a broad range of ideas. Writing systems are generally classified according to how their symbols, called graphemes, relate to units of language. Phonetic writing systems – which include alphabets and syllabaries – use graphemes that correspond to sounds in the corresponding spoken language. Alphabets use graphemes called letters that generally correspond to spoken phonemes. They are typically divided into three sub-types: Pure alphabets use letters to represent both consonant and vowel sounds, abjads generally only use letters representing consonant sounds, and abugidas use letters representing consonant–vowel pairs. Syllabaries use graphemes called syllabograms that represent entire syllables or moras. By contrast, logographic (or morphographic) writing systems use graphemes that represent the units of meaning in a language, such as its words or morphemes.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It narrates the decipherment of one script."}, {"id": "B", "text": "It argues that logographic systems are superior."}, {"id": "C", "text": "It compares writing with speech in detail."}, {"id": "D", "text": "It defines writing systems, describes their origins, and classifies them by how symbols relate to language."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Writing system", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Writing_system', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
