INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M32-CE008', 'HDSAT-RW-M32-CE008', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'A writing system is any conventional system for representing a particular language using a set of symbols (called a script), as well as the rules those symbols encode. The earliest of conventional writing systems appeared during the late 4th millennium BC. Throughout history, each independently invented writing system gradually emerged from a system of proto-writing, where a small number of ideographs were used in a manner incapable of fully encoding language, and thus lacking the ability to express a broad range of ideas. Writing systems are generally classified according to how their symbols, called graphemes, relate to units of language. Phonetic writing systems – which include alphabets and syllabaries – use graphemes that correspond to sounds in the corresponding spoken language. Alphabets use graphemes called letters that generally correspond to spoken phonemes. They are typically divided into three sub-types: Pure alphabets use letters to represent both consonant and vowel sounds, abjads generally only use letters representing consonant sounds, and abugidas use letters representing consonant–vowel pairs. Syllabaries use graphemes called syllabograms that represent entire syllables or moras. By contrast, logographic (or morphographic) writing systems use graphemes that represent the units of meaning in a language, such as its words or morphemes.', 'Which quotation from the text most directly supports the claim that writing systems are classified by symbol function?', '[{"id": "A", "text": "Phonetic writing systems – which include alphabets and syllabaries – use graphemes that correspond to sounds."}, {"id": "B", "text": "Writing systems are generally classified according to how their symbols, called graphemes, relate to units of language."}, {"id": "C", "text": "The earliest of conventional writing systems appeared during the late 4th millennium BC."}, {"id": "D", "text": "A writing system is any conventional system for representing a particular language using a set of symbols."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Writing system", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Writing_system', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M32-CE008', 'B', ARRAY['B']::TEXT[], 'The correct quotation states the basis for classifying writing systems.', '{"D": "This sentence defines a writing system.", "C": "This sentence dates the earliest systems.", "A": "This sentence describes phonetic systems."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M32-CI009', 'HDSAT-RW-M32-CI009', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'A dialect is a variety of language spoken by a particular group of people. This may include dominant and standardized varieties as well as vernacular, unwritten, or non-standardized varieties, such as those used in developing countries or isolated areas. The dialects of the same language are mainly distinguished from each other by differences in linguistic features such as phonology, morphology, syntax and vocabulary. The term "dialect" is most often used to refer to regional dialects—i.e., linguistic varieties that are spoken in a particular geographical region, distinguished from those of other regions. Varieties associated with groups defined in other ways may be referred to as "dialects", or with more specialized terms such as sociolect (the dialect of a social class) and ethnolect (the dialect of an ethnic group). An idiolect is the unique variety of language used by a particular individual. The non-standard dialects of a language with a writing system will operate at different degrees of distance from the standardized written form. An oral dialect or idiolect may be portrayed in written form with eye dialect. == Standard and nonstandard dialects == A standard dialect, also known as a "standardized language", is supported by institutions.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Dialects differ only in pronunciation."}, {"id": "B", "text": "A dialect is a language variety used by a group, distinguished by features such as phonology, vocabulary, and syntax."}, {"id": "C", "text": "Only nonstandard varieties count as dialects."}, {"id": "D", "text": "A dialect is a separate language with no relation to others."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Dialect", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Dialect', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M32-CI009', 'B', ARRAY['B']::TEXT[], 'The passage defines dialects, describes types, and discusses standard and nonstandard varieties.', '{"D": "The text defines a dialect as a variety spoken by a particular group.", "A": "The text lists phonology, morphology, syntax, and vocabulary.", "C": "The text includes dominant and standardized varieties as well as vernacular ones."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M32-INF009', 'HDSAT-RW-M32-INF009', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'A dialect is a variety of language spoken by a particular group of people. This may include dominant and standardized varieties as well as vernacular, unwritten, or non-standardized varieties, such as those used in developing countries or isolated areas. The dialects of the same language are mainly distinguished from each other by differences in linguistic features such as phonology, morphology, syntax and vocabulary. The term "dialect" is most often used to refer to regional dialects—i.e., linguistic varieties that are spoken in a particular geographical region, distinguished from those of other regions. Varieties associated with groups defined in other ways may be referred to as "dialects", or with more specialized terms such as sociolect (the dialect of a social class) and ethnolect (the dialect of an ethnic group). An idiolect is the unique variety of language used by a particular individual. The non-standard dialects of a language with a writing system will operate at different degrees of distance from the standardized written form. An oral dialect or idiolect may be portrayed in written form with eye dialect. == Standard and nonstandard dialects == A standard dialect, also known as a "standardized language", is supported by institutions.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M32-INF009', 'A', ARRAY['A']::TEXT[], 'If an idiolect is individually unique, each speaker has one.', '{"C": "A variety unique to an individual applies to each speaker.", "B": "Identical idiolects would contradict uniqueness.", "D": "Every speaker uses some variety of language."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M32-TS009', 'HDSAT-RW-M32-TS009', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'A dialect is a variety of language spoken by a particular group of people. This may include dominant and standardized varieties as well as vernacular, unwritten, or non-standardized varieties, such as those used in developing countries or isolated areas. The dialects of the same language are mainly distinguished from each other by differences in linguistic features such as phonology, morphology, syntax and vocabulary. The term "dialect" is most often used to refer to regional dialects—i.e., linguistic varieties that are spoken in a particular geographical region, distinguished from those of other regions. Varieties associated with groups defined in other ways may be referred to as "dialects", or with more specialized terms such as sociolect (the dialect of a social class) and ethnolect (the dialect of an ethnic group). An idiolect is the unique variety of language used by a particular individual. The non-standard dialects of a language with a writing system will operate at different degrees of distance from the standardized written form. An oral dialect or idiolect may be portrayed in written form with eye dialect. == Standard and nonstandard dialects == A standard dialect, also known as a "standardized language", is supported by institutions.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It argues that standard dialects are the only correct forms."}, {"id": "B", "text": "It compares dialects with sign languages."}, {"id": "C", "text": "It defines dialect, describes regional and social varieties, and distinguishes standard from nonstandard forms."}, {"id": "D", "text": "It narrates the history of one regional dialect."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Dialect", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Dialect', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
